// Objects merge field by field; arrays and plain values replace; null removes the field
function mergeFacts(base: any, patch: any): any {
  const out = { ...base };
  for (const [key, value] of Object.entries(patch)) {
    if (value === null) delete out[key];
    else if (typeof value === 'object' && !Array.isArray(value) && typeof out[key] === 'object' && out[key] !== null) out[key] = mergeFacts(out[key], value);
    else out[key] = value;
  }
  return out;
}

const factPatches = countryFacts.countries as Record<string, unknown>;

export const countriesData: Record<string, CountryData> = Object.fromEntries(
  Object.entries(baseCountriesData).map(([id, country]) => [id, factPatches[id] ? mergeFacts(country, factPatches[id]) : country]),
);

export const countryList: CountryData[] = Object.values(countriesData);

export function getCountryById(id: string): CountryData | undefined {
  if (!id) return undefined;
  if (countriesData[id]) return countriesData[id];
  const padded = id.padStart(3, '0');
  if (countriesData[padded]) return countriesData[padded];
  const unpadded = String(parseInt(id, 10));
  if (countriesData[unpadded]) return countriesData[unpadded];
  return undefined;
}

export function getCountryByName(name: string): CountryData | undefined {
  if (!name) return undefined;
  const lower = name.toLowerCase().trim();
  return countryList.find(c => 
    c.name.toLowerCase() === lower || 
    c.officialName.toLowerCase() === lower ||
    c.code.toLowerCase() === lower ||
    c.code3.toLowerCase() === lower
  );
}

export function searchCountries(query: string): CountryData[] {
  if (!query || !query.trim()) return countryList;
  const q = query.toLowerCase().trim();
  return countryList.filter(c => 
    c.name.toLowerCase().includes(q) || 
    c.code.toLowerCase().includes(q) || 
    c.code3.toLowerCase().includes(q) || 
    c.capital.toLowerCase().includes(q) || 
    c.continent.toLowerCase().includes(q)
  );
}
